{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": [
        "C42"
      ],
      "claim": "C42: In 20 HIV-infected subjects, emtricitabine had a mean absolute oral bioavailability of 93% after multiple-dose oral administration, supporting F ≥ 20%."
    },
    {
      "card_ids": [
        "C59"
      ],
      "claim": "C59: In patients with asymptomatic HIV infection, lamivudine as a single oral tablet dose had an absolute bioavailability of 93.1%, supporting F ≥ 20%."
    },
    {
      "card_ids": [
        "C36"
      ],
      "claim": "C36: In healthy male volunteers, the absolute bioavailability of an 8-mg oral ondansetron solution averaged 71 ± 14%, supporting F ≥ 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All condition-matched numeric absolute bioavailability records across the supplied evidence molecules are ≥20%, with multiple direct human measurements mostly in the 35–100% range; therefore high bioavailability is better supported.",
  "evidence_gaps": [
    "Molecule 1 includes didanosine records C49 and C47 grouped with emtricitabine records; these inconsistent cards were discounted due to provenance conflict.",
    "Molecule 7 provides only qualitative 'high bioavailability' without a numeric absolute F value, so it was not used as a quantitative basis.",
    "Fed-state didanosine records C33 and C34 were below 20% but were discounted as altered conditions; fasting records support high bioavailability."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": [
    "C42",
    "C59",
    "C36"
  ],
  "revision_action": "initial",
  "supportive_card_ids": [
    "C42",
    "C59",
    "C36"
  ]
}

